import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiCodex","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/codex/index.md","filePath":"en/modules/codex/index.md","lastUpdated":0}`),a={name:`en/modules/codex/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakicodex" tabindex="-1">EmakiCodex <a class="header-anchor" href="#emakicodex" aria-label="Permalink to “EmakiCodex”">​</a></h1><p>EmakiCodex contains two independent codex models. <code>advancements/*.yml</code> defines and registers vanilla advancement pages and nodes, while <code>codex/*.yml</code> defines categories, entries, unlock conditions, and rewards for a separate category-entry GUI. The two models can be linked through advancement unlocks, but <code>page_id</code> and <code>category_id</code> are not interchangeable.</p><p>When PacketEvents is installed, EmakiCodex can inject configured node coordinates into the client advancement tree and re-push the registered tree to online players. Without PacketEvents, vanilla advancements still register normally, but node placement is handled by the vanilla client parent tree and online players may need to reconnect after a reload to see the updated tree. The category-entry GUI does not require PacketEvents; its action rewards still run through CoreLib, while attribute rewards are derived from the current configuration.</p><h2 id="basic-information" tabindex="-1">Basic information <a class="header-anchor" href="#basic-information" aria-label="Permalink to “Basic information”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Runtime/POM version</td><td><code>1.1.0</code></td></tr><tr><td>API Jar</td><td><code>emaki-codex-api-1.1.0.jar</code></td></tr><tr><td>Default config structure version</td><td><code>1.1.0</code></td></tr><tr><td>Main class</td><td><code>emaki.jiuwu.craft.codex.EmakiCodexPlugin</code></td></tr><tr><td>Main command</td><td><code>/codex</code></td></tr><tr><td>Alias</td><td><code>/ecodex</code></td></tr><tr><td>Required dependency</td><td>EmakiCoreLib</td></tr><tr><td>Optional dependencies</td><td>PlaceholderAPI, PacketEvents, MythicMobs</td></tr><tr><td>Minimum server</td><td>Paper 1.21.8+ (<code>api-version: 1.21.8</code>, <code>folia-supported: true</code>)</td></tr><tr><td>Java</td><td>Java 25</td></tr><tr><td>Main permissions</td><td><code>emakicodex.use</code> (default true), <code>emakicodex.reload</code> (op), <code>emakicodex.debug</code> (op), <code>emakicodex.admin</code> (op)</td></tr></tbody></table><p>The POM/runtime/API and default <code>config.yml</code> version is <code>1.1.0</code>. The internal <code>AppConfig.CURRENT_VERSION = &quot;1.0.14&quot;</code> is a configuration-migration structure constant, not a plugin release version or API coordinate.</p><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to “Pages”">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./commands.html">Commands</a></td><td><code>/codex</code> and <code>/ecodex</code> subcommands, permissions, and examples.</td></tr><tr><td><a href="./configuration.html">Configuration</a></td><td>The entry points and version semantics of <code>config.yml</code>, <code>codex/*.yml</code>, <code>gui/codex_gui.yml</code>, and <code>lang/*.yml</code>.</td></tr><tr><td><a href="./advancements.html">Advancements</a></td><td>The page and node fields of <code>advancements/*.yml</code>, node key rules, coordinate rules, and completion actions.</td></tr><tr><td><a href="./gui.html">Category GUI</a></td><td>Category/entry definitions, four-state progress, activation and one-time claims, layout types, and placeholders.</td></tr><tr><td><a href="./triggers.html">Triggers</a></td><td>Vanilla advancement <code>triggers.entries</code> and category-entry <code>unlock.triggers</code>.</td></tr><tr><td><a href="./corelib-actions.html">CoreLib Actions</a></td><td>The seven action stages registered by EmakiCodex into CoreLib&#39;s ActionRegistry.</td></tr><tr><td><a href="./api.html">API</a></td><td>How third-party plugins call the vanilla-advancement layer through <code>emaki-codex-api</code>.</td></tr></tbody></table><h2 id="core-features" tabindex="-1">Core features <a class="header-anchor" href="#core-features" aria-label="Permalink to “Core features”">​</a></h2><ul><li><strong>Vanilla advancement codex</strong>: each <code>advancements/*.yml</code> file is one vanilla advancement tab, with node keys like <code>emakicodex:&lt;page&gt;/&lt;node&gt;</code>.</li><li><strong>Category-entry codex</strong>: each <code>codex/*.yml</code> file defines one GUI category; composite entry ids use <code>&lt;category_id&gt;/&lt;entry_id&gt;</code>, ordered by <code>order</code>.</li><li><strong>Four entry states</strong>: entries move through locked, unlocked, activated, and claimed; activation and claiming are separate operations.</li><li><strong>Two unlock paths</strong>: <code>unlock.triggers</code> listens to shared events, while <code>unlock.advancements</code> listens to vanilla advancements; either path can unlock an entry.</li><li><strong>Two reward paths</strong>: <code>rewards.attributes</code> contributes live attributes after activation, while <code>rewards.actions</code> runs once when the player claims the reward.</li><li><strong>Manual grant/revoke and admin entry control</strong>: administrators use <code>/codex grant</code> and <code>/codex revoke</code> for vanilla nodes, and <code>admin unlock/reset</code> for category entries.</li><li><strong>Action grants and announcements</strong>: CoreLib exposes five advancement operations plus <code>codex_show_toast</code> and <code>codex_broadcast_achievement</code>.</li><li><strong>Gameplay triggers</strong>: vanilla nodes use <code>triggers.entries</code>; category entries use <code>unlock.triggers</code> with shared gameplay events and conditions.</li><li><strong>Completion and claim actions</strong>: vanilla completion runs <code>actions.complete</code>; category claims run <code>rewards.actions</code>.</li><li><strong>PacketEvents coordinate channel</strong>: when PacketEvents is installed and <code>advancement.packet_coordinates</code> is enabled, vanilla node <code>x</code> / <code>y</code> values are sent to the client advancement screen.</li></ul><h2 id="file-layout" tabindex="-1">File layout <a class="header-anchor" href="#file-layout" aria-label="Permalink to “File layout”">​</a></h2><p>After startup, EmakiCodex mainly uses these files:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiCodex/</span></span>
<span class="line"><span>├─ config.yml</span></span>
<span class="line"><span>├─ advancements/</span></span>
<span class="line"><span>│  └─ example_page.yml</span></span>
<span class="line"><span>├─ codex/</span></span>
<span class="line"><span>│  └─ example_category.yml</span></span>
<span class="line"><span>├─ gui/</span></span>
<span class="line"><span>│  └─ codex_gui.yml</span></span>
<span class="line"><span>├─ data/</span></span>
<span class="line"><span>│  └─ &lt;player-uuid&gt;.yml</span></span>
<span class="line"><span>└─ lang/</span></span>
<span class="line"><span>   ├─ zh_CN.yml</span></span>
<span class="line"><span>   └─ en_US.yml</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td>Main settings for default resource release, advancement registration, PacketEvents coordinates, and trigger enablement; <code>version</code> is currently <code>1.1.0</code>.</td></tr><tr><td><code>advancements/*.yml</code></td><td>Vanilla advancement pages. Each file defines one page, one root node, and any number of child nodes.</td></tr><tr><td><code>codex/*.yml</code></td><td>Category-entry definitions. Each file defines one GUI category; the composite entry id is <code>&lt;category_id&gt;/&lt;entry_id&gt;</code>.</td></tr><tr><td><code>gui/codex_gui.yml</code></td><td>Category-entry GUI template; functional slots must declare an explicit <code>type</code>.</td></tr><tr><td><code>data/&lt;uuid&gt;.yml</code></td><td>Per-player unlocked, activated, and claimed state; attribute values are derived from current configuration rather than stored.</td></tr><tr><td><code>lang/*.yml</code></td><td>Command, GUI, reload, and console messages.</td></tr></tbody></table><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to “Quick start”">​</a></h2><ol><li>Put <code>EmakiCoreLib-*.jar</code> and <code>EmakiCodex-*.jar</code> into the server <code>plugins/</code> directory.</li><li>Do not put <code>emaki-codex-api-*.jar</code> into <code>plugins/</code>; the API Jar is only for developer compile dependencies.</li><li>After first startup, inspect <code>plugins/EmakiCodex/advancements/example_page.yml</code>.</li><li>After editing or adding pages, run:</li></ol><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/codex reload</span></span></code></pre></div><ol start="5"><li>Open the category-entry codex GUI:</li></ol><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/codex codex</span></span></code></pre></div><ol start="6"><li>Grant the sample vanilla node for testing:</li></ol><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/codex grant Steve example/first_step</span></span></code></pre></div><ol start="7"><li>Manage a category entry with its composite id:</li></ol><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/codex admin unlock Steve example/first_blood</span></span>
<span class="line"><span>/codex admin reset Steve example/first_blood</span></span></code></pre></div><p>The full key form also works:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/codex grant Steve emakicodex:example/first_step</span></span></code></pre></div><h2 id="two-configuration-models-at-a-glance" tabindex="-1">Two configuration models at a glance <a class="header-anchor" href="#two-configuration-models-at-a-glance" aria-label="Permalink to “Two configuration models at a glance”">​</a></h2><p>One <code>advancements/*.yml</code> file defines one vanilla advancement page:</p><ul><li>Page level: <code>page_id</code> (the key path prefix), <code>title</code>, <code>background</code>, <code>root</code>.</li><li>Node level: <code>icon</code>, <code>title</code>, <code>description</code>, <code>frame</code>, <code>parent</code>, <code>x</code> / <code>y</code>, <code>toast</code>, <code>announce</code>, <code>hidden</code>.</li><li>Node completion actions go in <code>actions.complete</code>, and gameplay triggers go in <code>triggers.entries</code>.</li></ul><p>One <code>codex/*.yml</code> file defines one category-entry page:</p><ul><li>Category level: <code>category_id</code>, <code>title</code>, <code>icon</code>, <code>order</code>, <code>entries</code>.</li><li>Entry level: <code>title</code>, <code>description</code>, <code>icon</code>, <code>hidden</code>, <code>unlock.triggers</code>, <code>unlock.advancements</code>, <code>rewards.attributes</code>, and <code>rewards.actions</code>.</li><li>Commands, GUI state, and data files use the composite id <code>&lt;category_id&gt;/&lt;entry_id&gt;</code>.</li></ul><p>Both trigger systems use CoreLib condition groups with <code>condition.type</code> and <code>condition.entries</code>. Vanilla nodes register as <code>emakicodex:&lt;page_id&gt;/&lt;node_id&gt;</code>. See <a href="./advancements.html">Advancements</a> and <a href="./gui.html">Category GUI</a> for the full field tables and interaction rules.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>Vanilla advancements and the category-entry GUI keep separate state; do not use <code>advancements/&lt;page_id&gt;</code> where <code>codex/&lt;category_id&gt;</code> is required.</li><li>Vanilla nodes are completed through Codex grants: commands, actions, the public API, or triggers award the internal <code>codex</code> criterion.</li><li><code>actions.complete</code> runs only on first vanilla completion; category <code>rewards.actions</code> runs only on the one-time claim.</li><li>Category <code>rewards.attributes</code> are not stored as numbers; they are derived from current configuration, so changing the reward config affects already activated players.</li><li>If advancement coordinates are enabled, configure <code>x</code> / <code>y</code> for every node in a page to avoid mixing explicit coordinates with client auto-layout.</li></ul>`,33)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};